func ProductAttributeSearch(data map[string]string) (result ProductAttributeParam, err error) {
	productCode := data["productCode"]

	query := elasticSearch.NewMatchQuery("productCode", productCode)

	client := elasticConn.EsClient
	esClient := client.Search()

	res, err := esClient.Index("main-prod-vm").
		Query(query).
		Do(context.Background())

	if err == nil {
		categoryAttributeList := &model.CategoryAttributeValueSearch{}
		for _, element := range res.Hits.Hits {
			err := json.Unmarshal(element.Source, &categoryAttributeList)
			if err != nil {
				return ProductAttributeParam{}, err
			}
		}
		// Extract the deepest non-zero category level
		cateArr := []string{categoryAttributeList.CATEGORYCODE4, categoryAttributeList.CATEGORYCODE3, 
		                     categoryAttributeList.CATEGORYCODE2, categoryAttributeList.CATEGORYCODE1}
		result.CategoryCode = cateArr[0]

		for i, value := range cateArr {
			if value != "0" {
				break
			}
			result.CategoryCode = cateArr[i+1]
		}

		iArr := MapToInt(categoryAttributeList)
		attributeValueSeqMap := make(map[int]string)
		result.AttributeValueSeqMap = attributeValueSeqMap
		result.AttributeValueSeqList = iArr

		// Map attribute value sequences to descriptions
		for i, value := range strings.Split(categoryAttributeList.SATTRIBUTEVALUEDESCRIPTION, "|") {
