#### Handler Implementation - Step 2
**File:** `/Users/admin/project/legacy/searchapi-elastic/handler/product-es.go` (Lines 3846-3975)

```go
// ProductAttributeValueSearch - 가져온 상품의 정보와, 해당 카테고리가 가지고있는 속성, 속성 값 들을 비교하여 매칭해줌.
func ProductAttributeValueSearch(param ProductAttributeParam) (result response.Result, err error) {
	client := elasticConn.EsClient
	esClient := client.Search()
	searchList := make([]*model.ProductAttributeValueSearchResult, 0)

	// Query for all attributes in the category
	matchQuery := elasticSearch.NewMatchQuery("CATEGORYSEQ", param.CategoryCode)
	query := elasticSearch.NewBoolQuery().Must(matchQuery)

	// Setup sorting
	sDisplaySort := elasticSearch.NewFieldSort("SDISPLAYSORT")
	attributeNameSort := elasticSearch.NewFieldSort("ATTRIBUTENAME")
	attributeSeqSort := elasticSearch.NewFieldSort("ATTRIBUTESEQ")
	mDisplaySort := elasticSearch.NewFieldSort("MDISPLAYSORT")

	// Search in attribute-value index
	res, err := esClient.Index("main-prod-attribute-value").
		Query(query).
		From(0).
		Size(1000).
		SortBy(sDisplaySort, attributeNameSort, attributeSeqSort, mDisplaySort).
		Do(context.Background())

	if err == nil {
		for _, element := range res.Hits.Hits {
			productAttributeInfo := &model.ProductAttributeValueSearch{}
			err := json.Unmarshal(element.Source, productAttributeInfo)

			if err != nil {
				return response.Result{}, err
			}

			// Build map of attribute value sequences to their names and descriptions
			attributeValueSeqMap := make(map[string][2]string)
			for i, _ := range productAttributeInfo.NATTRIBUTEVALUESEQS {
				var values [2]string
				values[0] = productAttributeInfo.SATTRIBUTEVALUENAMES[i]
				values[1] = productAttributeInfo.DESCRIPTIONLISTVALUESEQS[i]
				attributeValueSeqMap[productAttributeInfo.NATTRIBUTEVALUESEQS[i]] = values
			}

			// Sort attribute values by display sort order
			var intArrToSort []int
			for _, value := range productAttributeInfo.NDISPLAYSORTS {
				val, _ := strconv.Atoi(value)
				intArrToSort = append(intArrToSort, val)
			}

			type SortStandard struct {
				nDisplaySeq              int
				nAttributeValueSeqs      string
				sAttributeValueNames     string
				descriptionListValueSeqs string
			}

			sortStandards := make([]SortStandard, len(intArrToSort))
			for i := range intArrToSort {
				sortStandards[i] = SortStandard{
					intArrToSort[i],
					productAttributeInfo.NATTRIBUTEVALUESEQS[i],
					productAttributeInfo.SATTRIBUTEVALUENAMES[i],
					productAttributeInfo.DESCRIPTIONLISTVALUESEQS[i],
				}
			}

			sort.Slice(sortStandards, func(i, j int) bool {
				return sortStandards[i].nDisplaySeq < sortStandards[j].nDisplaySeq
			})

			// Reorder attributes by display sort
			for i := range sortStandards {
				productAttributeInfo.NATTRIBUTEVALUESEQS[i] = sortStandards[i].nAttributeValueSeqs
				productAttributeInfo.SATTRIBUTEVALUENAMES[i] = sortStandards[i].sAttributeValueNames
				productAttributeInfo.DESCRIPTIONLISTVALUESEQS[i] = sortStandards[i].descriptionListValueSeqs
			}

			flag := false

			// Match product's attribute values with category attributes
			for _, key := range productAttributeInfo.NATTRIBUTEVALUESEQS {
				element := attributeValueSeqMap[key]
				val, _ := strconv.Atoi(key)

				if productAttributeInfo.MULTISELECTTYPE != "S" {
					// For non-single select attributes, add all matches
					productAttributeInfo.ATTRIBUTEVALUESEQ = key
					productAttributeInfo.ATTRIBUTEVALUENAME = element[0]
					productAttributeInfo.DESCRIPTIONLISTVALUESEQ = element[1]

					if binarySearch(param.AttributeValueSeqList, val) {
						productAttributeInfo.ATTRIBUTEVALUEDESCRIPTION = param.AttributeValueSeqMap[val]
					}

					searchList = addProductAttributeInfo(productAttributeInfo, searchList)
					productAttributeInfo.ATTRIBUTEVALUEDESCRIPTION = ""
				} else {
					// For single select attributes, add only if matches product's values
					if binarySearch(param.AttributeValueSeqList, val) {
						productAttributeInfo.ATTRIBUTEVALUESEQ = key
						productAttributeInfo.ATTRIBUTEVALUENAME = element[0]
						productAttributeInfo.DESCRIPTIONLISTVALUESEQ = element[1]
						productAttributeInfo.ATTRIBUTEVALUEDESCRIPTION = param.AttributeValueSeqMap[val]
						searchList = addProductAttributeInfo(productAttributeInfo, searchList)
						flag = true
						break
					}
				}
			}

			if !flag && productAttributeInfo.MULTISELECTTYPE == "S" {
				searchList = addProductAttributeInfo(productAttributeInfo, searchList)
			}
		}
	}

	searchList = preProcessSearchList(searchList)

	result.SearchList = searchList
	result.Total_count = len(searchList)

	return
}
```

**Step 2 Details:**
- Searches the `main-prod-attribute-value` index for all attributes in the product's category
- Sorts results by: `SDISPLAYSORT`, `ATTRIBUTENAME`, `ATTRIBUTESEQ`, `MDISPLAYSORT`
- For each category attribute, checks if it matches the product's attribute values
- Handles two types of attributes:
  - **Non-single select (MULTISELECTTYPE != "S"):** Includes all matching attribute values
  - **Single select (MULTISELECTTYPE == "S"):** Includes only if the attribute value matches the product's values
- Returns a list of `ProductAttributeValueSearchResult` objects with fully matched and described attributes

**Return Type (Step 2):** `ProductAttributeValueSearchResult`
```go
type ProductAttributeValueSearchResult struct {
	ATTRIBUTESEQ              string `json:"attributeSeq"`
	ATTRIBUTENAME             string `json:"attributeName"`
	ATTRIBUTEUNIT             string `json:"attributeUnit"`
	ATTRIBUTEUNITPOSITION     string `json:"attributeUnitPosition"`
	MULTISELECTTYPE           string `json:"multiSelectType"`
	DESCRIPTIONLISTSEQ        string `json:"descriptionListSeq"`
	ATTRIBUTEVALUESEQ         string `json:"attributeValueSeq"`
	ATTRIBUTEVALUENAME        string `json:"attributeValueName"`
	BUNDLETYPE                string `json:"bundleType"`
	ATTRIBUTEVALUEDESCRIPTION string `json:"attributeValueDescription"`
	DESCRIPTIONLISTVALUESEQ   string `json:"descriptionListValueSeq"`
	GROUPNAME                 string `json:"groupName"`
	GROUPCODE                 int    `json:"groupCode"`
}
